#include <iostream>
using namespace std;

int main() {
    int h, n;
    cin >> h >> n;
    h -= 1;
    n -= 1;
    int left_pointer = 0;
    int right_pointer = 2 << h;
    bool left_flag = true;
    int moves = 0;
    int iteration = 0;
    while (right_pointer - left_pointer > 1) {
        int center = (left_pointer + right_pointer) / 2;
        if (left_flag == (n < center)) {
            moves += 1;
        } else {
            moves += 1 << (h - iteration + 1);
        }
        if (n < center) {
            right_pointer = center;
            left_flag = false;
        } else {
            left_pointer = center;
            left_flag = true;
        }
        iteration++;
    }
    cout << moves << endl;
    return 0;
}
